INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷一百〇四", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/c55e23db2fe30e33712619797f5300a286a58c03/content/books/zizhi-tongjian/vol-286/year-0947/part-08/sources/library/jiuwudaishi-104-li-advice/source.txt", "note": "《旧五代史》卷一百〇四，段落 jiu-wudaishi-205deb4a7860-p002508；EPUB电子本，纸本及异文待核", "id": "5f1bd8fd-5161-5d18-b53e-00655e2b57a7"}, {"title": "资治通鉴·后汉纪一", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/c55e23db2fe30e33712619797f5300a286a58c03/content/books/zizhi-tongjian/vol-286/year-0947/part-08/sources/library/tongjian-286-947-li-wuyue/source.txt", "note": "《资治通鉴》后汉纪一，段落 zizhi-tongjian-a63549944a71-p003399；电子底本待考，分段待核", "id": "3b9e025c-ba6d-5964-9920-6d85a4f59344"}, {"title": "新五代史·卷十七", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/c55e23db2fe30e33712619797f5300a286a58c03/content/books/zizhi-tongjian/vol-286/year-0947/part-08/sources/library/xinwudaishi-017-feng-poison/source.txt", "note": "《新五代史》卷十七，段落 xin-wudaishi-b08f244b9241-p000579；EPUB电子本，纸本及异文待核", "id": "a76f4f07-b2a1-5f45-81a7-c9fd71300081"}, {"title": "资治通鉴·后汉纪一", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/576d9a100a90791fb2103eff8dc0a2a9ed251986/content/books/zizhi-tongjian/vol-286/year-0947/part-07/sources/library/tongjian-286-947-accession/source.txt", "note": "《资治通鉴》后汉纪一，段落 zizhi-tongjian-a63549944a71-p003398；电子底本待考，分段待核", "id": "b5c70da1-1238-5cff-83ff-fba29fe485de"}, {"title": "旧五代史·卷九十九", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/576d9a100a90791fb2103eff8dc0a