ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "刘知远", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷271贞明五年条所见人物：刘知远。", "biography": null, "status": "draft", "id": "69fa3b4b-2f0d-5799-bbf5-e378af9816e1"}, {"name": "石重贵", "aliases": ["石重貴"], "era": "五代十国", "birth_year": 914, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：石重贵，被叙侄子及养子身份者。", "biography": null, "status": "draft", "id": "2741e60a-9bf9-56a7-b30d-3db439caa139"}, {"name": "永宁公主（石敬瑭妻）", "aliases": ["永宁公主", "永寧公主"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：永宁公主（石敬瑭妻），与从荣异母的公主。", "biography": null, "status": "draft", "id": "fddc7a96-9cc5-5313-ac24-2c3189930825"}, {"name": "薛超", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋亲军将。946年十二月癸酉，石重贵准备与后宫人员投火自尽时，他将皇帝拦住。生卒年、籍贯未载。", "biography": null, "status": "draft", "id": "35a4e56e-b5d8-58d2-b411-af3f6cf2c20f"}, {"name": "冯氏（石重贵后）", "aliases": ["吴国夫人冯氏", "馮氏（石重贵后）"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "冯濛的女儿、冯玉的妹妹。先嫁石重胤，夫死后守寡；石敬瑭去世后被石重贵纳入宫中，943年十月戊申由吴国夫人立为皇后，随后参与政务。具体个人名字与生卒年未载。", "biography": null, "status": "draft", "id": "a9036cf2-4b6b-5883-a952-511979eb35f7"}, {"name": "耶律德光", "aliases": ["德光"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：耶律德光，守西楼、受号者。", "biography": null, "status": "draft", "id": "64c415ac-57fe-571c-8c6f-3ed68fb726da"}, {"name": "耿崇美", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "契丹通事。946年十二月杜重威降后，奉命到易州诱说守军投降，并杀死刺史郭璘。生卒年未载。", "biography": null, "status": "draft", "id": "60458ef5-e4bc-5d29-b338-25090e903595"}, {"name": "高唐英", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "契丹所任地方长官。947年二月刘知远即位后，被任命为彰德节度使；梁晖袭取相州时，他尚未到任。《旧五代史》同记相州節度使，《辽史》官号另作昭德，分别保留。生卒年未载。", "biography": null, "status": "draft", "id": "4b35bffc-c928-554e-8e55-22b4618620ab"}, {"name": "崔廷勋", "aliases": ["崔廷勛"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "河内人。947年正月《资治通鉴》称他为大同节度使兼侍中，耶律德光派他率兵看守迁到封禅寺的石重贵及家人。《旧五代史》称为蕃大将崔廷勋，未另建同名人；生卒年未载。", "biography": null, "status": "draft", "id": "43995ba6-a8ce-5d3a-86dd-43d3def50195"}, {"name": "梁晖", "aliases": ["梁暉"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "滏阳武装首领，率数百人向刘知远请求效力，受李谷指示袭击相州。947年二月丁丑夜攻入相州，守将突围离开，梁晖自称留后并上报。生卒年暂未录入。", "biography": null, "status": "draft", "id": "5d3513b4-fa20-5947-9ffb-c3d71ae4cbfc"}, {"name": "李谷", "aliases": ["李穀"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：李谷，汝阴进士、送别友人。", "biography": null, "status": "draft", "id": "33cb8b51-1e37-5d5f-ab22-b339b991020d"}, {"name": "李氏（刘知远妻）", "aliases": ["李氏（後漢高祖后）"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "晋阳人，刘知远的妻子。947年二月劝丈夫停止征民财劳军，改用宫中积蓄，建议获采纳。《旧五代史》称高祖皇后李氏，此时《通鉴》称夫人李氏，正式册后另在后续时间录入。名字与生卒年暂未录入。", "biography": null, "status": "draft", "id": "10b635fe-af1e-534c-891a-5b82288872e1"}, {"name": "程昭悦", "aliases": ["程昭悅"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "钱塘富人，通过财物结交杜昭达、阚璠，得以接近钱弘佐。后来谋排阚璠，诬告阚璠、杜昭达拥立钱仁俊，使两人遇害、钱仁俊失官被囚，并清除百余权位与自己相当或被自己忌恨的人。生卒年本段未载。", "biography": null, "status": "draft", "id": "4dcc2f3e-2f3d-5dcd-b573-598392035d56"}, {"name": "钱弘佐", "aliases": ["錢弘佐"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "钱传瓘之子，母亲许氏。939年条下的王室家属追述提及他，出生年份本句未载。", "biography": null, "status": "draft", "id": "0d604e68-f71f-5263-9e8f-80de6e9feb32"}, {"name": "水丘昭券", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "临安人，吴越内都监使。946年福州求救时，他主张出兵。钱弘佐让他掌管用兵，他因忌惮程昭悦而让出此事。原文未载生卒年。", "biography": null, "status": "draft", "id": "f1cf3b01-3f76-5d76-92a7-87fd41eb433c"}, {"name": "储温", "aliases": ["儲溫"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "吴越内牙指挥使。947年二月受钱弘佐命令，等待程昭悦回宅后拘捕他，送往东府。生卒年未载。", "biography": null, "status": "draft", "id": "42b03934-1602-5538-8d73-f0434e0bb38a"}, {"name": "钱仁俊", "aliases": ["錢仁俊"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：钱仁俊，从子、受遣告谕者。", "biography": null, "status": "draft", "id": "8ba65976-a158-523f-a631-fac69d75de34"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
