tus": "draft", "id": "bfc62cf5-ea37-53c8-8e40-fd1c59cabad9", "subject_id": "a02bd9ac-cefd-5710-9358-02aaea4f73ca", "source_id": "b5c70da1-1238-5cff-83ff-fba29fe485de"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "947年二月甲戌出行后，具体日未载", "citation": "卷286·天福十二年（947年二月及追述）·zztj-v286-y0947-p036·原文件第41行", "note": "原文：至寿阳，闻已过恒州数日，乃留兵戍承天军而还。；核对说明：按《资治通鉴》及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "7b5d962d-483e-56ab-90f8-dd68438ccbb9", "subject_id": "a02bd9ac-cefd-5710-9358-02aaea4f73ca", "source_id": "b5c70da1-1238-5cff-83ff-fba29fe485de"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "刘知远：得知已错过晋帝行程，留兵守承天军并返回。", "citation": "卷286·天福十二年（947年二月及追述）·zztj-v286-y0947-p036·原文件第41行", "note": "原文：至寿阳，闻已过恒州数日，乃留兵戍承天军而还。；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "6de63d6a-fbe1-5c80-8caf-aced2a078239", "subject_id": "223c9d53-a7eb-58bd-b754-d0a138bb993e", "source_id": "b5c70da1-1238-5cff-83ff-fba29fe485de"}, {"subject_table": "event", "field_path": "description", "claim_text": "《旧五代史》也记得知晋帝已过而返回。", "citation": "《旧五代史》卷九十九，段落 jiu-wudaishi-205deb4a7860-p002427；EPUB电子本，纸本及异文待核", "note": "原文：聞其已過，乃還。；核对说明：该书未在此句给留兵细节，由《资治通鉴》单独支持；不扩大《旧五代史》摘录范围。", "status": "draft", "id": "25c6a757-fbed-5e7c-8776-5ee2e29c700b", "subject_id": "a02bd9ac-cefd-5710-9358-02aaea4f73ca", "source_id": "ee32ab47-1d43-56d4-8578-da743dfdb40e"}, {"subject_table": "event", "field_path": "description", "claim_text": "契丹停止供给石重贵北迁队伍，随行官员和宫女采果实草叶充饥。", "citation": "卷286·天福十二年（947年二月及追述）·zztj-v286-y0947-p037·原文件第42行", "note": "原文：晋主既出寨，契丹无复供给，从官、宫女，皆自采木实、草叶而食之。；核对说明：官员宫女没有逐一姓名，不自动关联所有前晋官员；未载具体死亡人数。", "status": "draft", "id": "9199d9b1-9071-596b-ad7e-75db856a77f3", "subject_id": "13140ba7-f503-50f6-83f8-cb5c10cbc46a", "source_id": "b5c70da1-1238-5cff-83ff-fba29fe485de"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "947年北迁途中，离寨之后，具体月日未载", "citation": "卷286·天福十二年（947年二月及追述）·zztj-v286-y0947-p037·原文件第42行", "note": "原文：晋主既出寨，契丹无复供给，从官、宫女，皆自采木实、草叶而食之。；核对说明：按《资治通鉴》及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "85feaa7b-b022-50d4-af19-38a20536439c", "subject_id": "13140ba7-f503-50f6-83f8-cb5c10cbc46a", "source_id": "b5c70da1-1238-5cff-83ff-fba29fe485de"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "石重贵：北迁队伍失去契丹供给。", "citation": "卷286·天福十二年（947年二月及追述）·zztj-v286-y0947-p037·原文件第42行", "note": "原文：晋主既出寨，契丹无复供给，从官、宫女，皆自采木实、草叶而食之。；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "adff0050-21b6-5a7c-9e4a-c0108c57f9a2", "subject_id": "458efcfc-bdf2-5b10-a6b1-0ccdee7964f9", "source_id": "b5c70da1-1238-5cff-83ff-fba29fe485de"}, {"subject_table": "event", "field_path": "description", "claim_text": "《旧五代史》记至榆关沙塞一带缺乏供给，宫女从官采木实野蔬充饥。", "citation": "《旧五代史》卷八十五，段落 jiu-wudaishi-205deb4a7860-p002052；EPUB电子本，纸本及异文待核", "note": "原文：至榆關沙塞之地，略無供給，每至宿頓，無非路次，一行乏食，宮女、從官但采木實野蔬，以救饑弊。；核对说明：补充缺粮的地点与行程，依各书原文保留，不换算具体日期。", "status": "draft", "id": "70323307-23e0-57a6-984f-7a2206681eb1", "subject_id": "13140ba7-f503-50f6-83f8-cb5c10cbc46a", "source_id": "548fcb32-173b-54f8-a340-102667e40687"}, {"subject_table": "event", "field_path": "description", "claim_text": "契丹迫石重贵及后妃在锦州礼拜阿保机墓。", "citation": "卷286·天福十二年（947年二月及追述）·zztj-v286-y0947-p037·原文件第42行", "note": "原文：至锦州，契丹令晋主及后妃拜契丹主阿保机墓。；核对说明：契丹是此处行动方，没有点名具体执行者，不能直接加耶律德光为亲自押送者。后妃没有逐一名单，不补所有人的参与。", "status": "draft", "id": "25b0ec1c-2316-56c3-b00f-622f082dc814", "subject_id": "c333a900-2a45-5dd6-ad78-20076aca0ea5", "source_id": "b5c70da1-1238-5cff-83ff-fba29fe485de"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "947年北迁至锦州时，具体月日未载", "citation": "卷286·天福十二年（947年二月及追述）·zztj-v286-y0947-p037·原文件第42行", "note": "原文：至锦州，契丹令晋主及后妃拜契丹主阿保机墓。；核对说明：按《资治通鉴》及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "d7171c42-ce75-577e-b41b-32eebac45afc", "subject_id": "c333a900-2a45-5dd6-ad78-20076aca0ea5", "source_id": "b5c70da1-1238-5cff-83ff-fba29fe485de"}, {"subject_table": "person_event", "field_path": "role", "claim